{"file_path":"src/errors.js","content":"/**
 * Error types used while parsing a configuration document.
 *
 * `SpecError` carries just the reason text for a single failure and is
 * thrown deep inside the recursive-descent parser, which has no notion of
 * which line it is working on. The per-line driver in parse.js catches it
 * and re-throws a `ParseError`, which pairs the reason with the 1-based
 * line number so the CLI can format `error: line N: <reason>`.
 */

export class SpecError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}
"}

