chunk.argumentsDelta:
{"file_path":"src/scanner.js","content":"/**
 * A cursor over a single line of the document. Values, names, headers and
 * comments can never cross a line boundary, so every parsing function in
 * this program operates on one `Scanner` per line.
 */

export class Scanner {
  constructor(line) {
    this.s = line
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.s.length
  }

  peek() {
    return this.s[this.pos]
  }

  /**
   * Skips spaces and tabs, then, if a `#` or `;` remains outside of a
   * quoted string, treats it as a comment and jumps to the end of the
   * line. This is only correct to call between tokens, never in the
   * middle of scanning a bare value token: a `#` glued directly onto a
   * value belongs to that token's text instead (see values.js).
   */
  skipWs() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) {
      this.pos++
    }
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
      this.pos = this.s.length
    }
  }
}

export function firstNonWs(line) {
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  return i
}
"}

