{"file_path":"src/nodes.js","content":"/**
 * The value tree the parser builds. Every node has a `kind`:
 *
 *   table            an object; `entries` is a Map from key text to node,
 *                     and `headerOpened` tracks whether a `[name]` header
 *                     (not a dotted key or an intermediate step) has
 *                     already made this exact table current, which is
 *                     what a second such header on the same path conflicts
 *                     with.
 *   array-of-tables   `items` is an array of table nodes.
 *   array             `items` is an array of value nodes.
 *   string, integer, float, boolean   `value` holds the JS value.
 *
 * A path is an array of segments, each either a key string or an array
 * index number, in the order they were walked from the document root.
 */

export function makeTable() {
  return { kind: 'table', entries: new Map(), headerOpened: false }
}

export function formatPath(segments) {
  let out = ''
  for (const seg of segments) {
    if (typeof seg === 'number') {
      out += `[${seg}]`
    } else {
      out += (out.length ? '.' : '') + seg
    }
  }
  return out
}

/** Ascending order by Unicode code point, as required for both output modes. */
export function compareKeys(a, b) {
  const ai = a[Symbol.iterator]()
  const bi = b[Symbol.iterator]()
  for (;;) {
    const an = ai.next()
    const bn = bi.next()
    if (an.done && bn.done) return 0
    if (an.done) return -1
    if (bn.done) return 1
    const ac = an.value.codePointAt(0)
    const bc = bn.value.codePointAt(0)
    if (ac !== bc) return ac - bc
  }
}

export function sortedKeys(table) {
  return Array.from(table.entries.keys()).sort(compareKeys)
}
"}

