{"file_path":"src/names.js","content":"import { SpecError } from './errors.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/

/** A basic (double-quoted) string, decoding its escapes. */
export function parseBasicString(scanner) {
  scanner.pos++ // opening quote
  let result = ''
  for (;;) {
    if (scanner.atEnd()) throw new SpecError('unterminated string')
    const c = scanner.peek()
    if (c === '"') {
      scanner.pos++
      return result
    }
    if (c === '\\') {
      scanner.pos++
      if (scanner.atEnd()) throw new SpecError('unterminated string')
      const e = scanner.peek()
      switch (e) {
        case '"':
          result += '"'
          scanner.pos++
          break
        case '\\':
          result += '\\'
          scanner.pos++
          break
        case 'n':
          result += '\n'
          scanner.pos++
          break
        case 't':
          result += '\t'
          scanner.pos++
          break
        case 'r':
          result += '\r'
          scanner.pos++
          break
        case '0':
          result += '\0'
          scanner.pos++
          break
        case 'u': {
          const hex = scanner.s.slice(scanner.pos + 1, scanner.pos + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw new SpecError('invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          scanner.pos += 5
          break
        }
        default:
          throw new SpecError(`invalid escape \\${e}`)
      }
    } else {
      result += c
      scanner.pos++
    }
  }
}

/** A literal (single-quoted) string, carrying no escapes. */
export function parseLiteralString(scanner) {
  scanner.pos++ // opening quote
  const start = scanner.pos
  for (;;) {
    if (scanner.atEnd()) throw new SpecError('unterminated string')
    if (scanner.peek() === "'") {
      const s = scanner.s.slice(start, scanner.pos)
      scanner.pos++
      return s
    }
    scanner.pos++
  }
}

/** A single name: a bare word, or a basic or literal quoted string. */
export function parseName(scanner) {
  scanner.skipWs()
  if (scanner.atEnd()) throw new SpecError('expected a name')
  const c = scanner.peek()
  if (c === '"') return parseBasicString(scanner)
  if (c === "'") return parseLiteralString(scanner)
  const start = scanner.pos
  while (!scanner.atEnd() && BARE_NAME_CHAR.test(scanner.peek())) scanner.pos++
  if (scanner.pos === start) throw new SpecError('expected a name')
  return scanner.s.slice(start, scanner.pos)
}

/** A dotted name: names joined by `.`, with spaces and tabs allowed around each dot. */
export function parseDottedName(scanner) {
  const parts = [parseName(scanner)]
  for (;;) {
    scanner.skipWs()
    if (!scanner.atEnd() && scanner.peek() === '.') {
      scanner.pos++
      parts.push(parseName(scanner))
    } else {
      break
    }
  }
  return parts
}
"}

