{"file_path":"src/render.js","content":"import { sortedKeys } from './nodes.js'

function jsonValue(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const lines = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${jsonValue(node.entries.get(k), indent + 1)}`)
      return `{\n${lines.join(',\n')}\n${pad}}`
    }
    case 'array-of-tables':
    case 'array': {
      if (node.items.length === 0) return '[]'
      const lines = node.items.map((item) => `${padIn}${jsonValue(item, indent + 1)}`)
      return `[\n${lines.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function renderJson(root) {
  return `${jsonValue(root, 0)}\n`
}

function typeName(node) {
  return node.kind === 'array-of-tables' ? 'array' : node.kind
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) {
      const child = node.entries.get(k)
      const childPath = path.length ? `${path}.${k}` : k
      out.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((child, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, out)
    })
  }
}

export function renderKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.map((line) => `${line}\n`).join('')
}
"}

